"""Delete artifacts generated by ``main.py`` and the dataset pipeline.

Destructive counterpart of :mod:`fia_ml.orchestration.run_all`. Entry point: ``clean.py``.

Safety model:

* Nothing is deleted without ``--run`` and a confirmation (``--yes`` skips the prompt).
* Only files under known generated-output roots are eligible. Inputs (``configs/``,
  ``src/``, ``data/reference/``, ``documentation/``, ``tests/``, ``.git/``) are never touched,
  even through a symlink or a misconfigured path.
* Placeholders (``.gitkeep``, ``__init__.py``) and structural folders are kept.
* Hard-to-recreate data is opt-in: FIA PDFs (``--include-pdfs``) and API caches
  (``--include-cache``). The FastF1 cache cannot be rebuilt without an F1 TV login.

Kept deliberately lightweight (stdlib + PyYAML) so it starts instantly and works even
when the ML stack is broken.
"""

from __future__ import annotations

import argparse
import os
import sys
from collections.abc import Callable, Iterable
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any

from fia_ml.paths import PROJECT_ROOT

PHASES: tuple[str, ...] = ("dataset", "v1", "v2", "nlp", "normative")
DATASET_STAGES: tuple[str, ...] = ("download", "parse", "build", "enrich", "validate")
DEFAULT_DATASET_STAGES: tuple[str, ...] = ("parse", "build", "enrich", "validate")

# Phases whose outputs were built from this phase's outputs (become stale if it is deleted).
DOWNSTREAM: dict[str, tuple[str, ...]] = {
    "dataset": ("v1", "v2", "nlp", "normative"),
    "v1": ("v2", "nlp", "normative"),
    "v2": (),
    "nlp": (),
    "normative": (),
}

# Only files below these folders can ever be deleted.
ALLOWED_ROOTS: tuple[str, ...] = (
    "data/raw",
    "data/interim",
    "data/processed",
    "dataset/csv",
    "ml_models",
    "reports",
)
# Never deleted, regardless of patterns or config values.
PROTECTED_ROOTS: tuple[str, ...] = (
    ".git",
    "configs",
    "src",
    "tests",
    "documentation",
    "data/reference",
)
PROTECTED_NAMES: frozenset[str] = frozenset({".gitkeep", "__init__.py"})

# Folders that belong to the repo layout; emptied but never removed.
STRUCTURAL_DIRS: frozenset[str] = frozenset(
    {
        "data",
        "data/raw",
        "data/raw/fia",
        "data/raw/race_data",
        "data/raw/race_data/ergast",
        "data/raw/race_data/fastf1_cache",
        "data/raw/race_data/openf1_cache",
        "data/interim",
        "data/interim/extracted_documents",
        "data/interim/enrichment_meta",
        "data/processed",
        "dataset",
        "dataset/csv",
        "ml_models",
        "ml_models/baseline",
        "ml_models/xgboost",
        "ml_models/xgboost_v2",
        "ml_models/nlp",
        "ml_models/normative",
        "reports",
        "reports/figures",
        "reports/model_reports",
        "reports/normative",
        "reports/normative/figures",
        "reports/tables",
    }
)

PREVIEW_LIMIT = 10


# --------------------------------------------------------------------------- config


def _read_yaml(path: Path) -> dict[str, Any]:
    if not path.exists():
        return {}
    try:
        import yaml
    except ImportError:  # pragma: no cover - PyYAML is a project dependency
        return {}
    with path.open(encoding="utf-8") as handle:
        data = yaml.safe_load(handle)
    return data if isinstance(data, dict) else {}


def _rel(value: Any, default: str) -> str:
    """Normalise a config path to a forward-slash path relative to the project root."""
    text = str(value or default).strip().replace("\\", "/").rstrip("/")
    return text or default


@dataclass(frozen=True)
class OutputPaths:
    """Output locations, read from configs so a changed path is still cleaned."""

    ergast_cache: str = "data/raw/race_data/ergast"
    fastf1_cache: str = "data/raw/race_data/fastf1_cache"
    openf1_cache: str = "data/raw/race_data/openf1_cache"
    processed: str = "data/processed"
    models: str = "ml_models"
    reports: str = "reports"
    nlp_models: str = "ml_models/nlp"
    normative_output: str = "data/processed/incidents_with_normative.parquet"
    normative_models: str = "ml_models/normative"
    normative_reports: str = "reports/normative"

    @classmethod
    def from_configs(cls, root: Path) -> "OutputPaths":
        configs = root / "configs"
        data = _read_yaml(configs / "data.yaml").get("paths", {}) or {}
        enrichment = _read_yaml(configs / "enrichment.yaml").get("openf1", {}) or {}
        v1 = _read_yaml(configs / "xgboost.yaml").get("paths", {}) or {}
        nlp = _read_yaml(configs / "bert.yaml").get("paths", {}) or {}
        normative = _read_yaml(configs / "normative.yaml").get("paths", {}) or {}
        d = cls()
        return cls(
            ergast_cache=_rel(data.get("ergast_cache"), d.ergast_cache),
            fastf1_cache=_rel(data.get("fastf1_cache"), d.fastf1_cache),
            openf1_cache=_rel(enrichment.get("cache_dir"), d.openf1_cache),
            processed=_rel(v1.get("processed"), d.processed),
            models=_rel(v1.get("models"), d.models),
            reports=_rel(v1.get("reports"), d.reports),
            nlp_models=_rel(nlp.get("models"), d.nlp_models),
            normative_output=_rel(normative.get("output"), d.normative_output),
            normative_models=_rel(normative.get("models_dir"), d.normative_models),
            normative_reports=_rel(normative.get("reports_dir"), d.normative_reports),
        )


# --------------------------------------------------------------------------- targets


@dataclass(frozen=True)
class Target:
    """A group of generated files, described by globs relative to the project root."""

    name: str
    phase: str
    description: str
    patterns: tuple[str, ...]
    hard_to_recreate: bool = False


def _season_tokens(seasons: list[int] | None) -> list[str]:
    return [str(s) for s in seasons] if seasons else ["*"]


def dataset_targets(
    stages: Iterable[str],
    seasons: list[int] | None,
    paths: OutputPaths,
    *,
    include_cache: bool,
) -> list[Target]:
    tokens = _season_tokens(seasons)
    stage_set = set(stages)
    targets: list[Target] = []

    if "download" in stage_set:
        targets.append(
            Target(
                "dataset:download",
                "dataset",
                "FIA PDFs, manifest.json, download_failures.json (re-download is slow, may hit the FIA WAF)",
                tuple(f"data/raw/fia/{s}/**/*" for s in tokens),
                hard_to_recreate=True,
            )
        )
    if "parse" in stage_set:
        targets.append(
            Target(
                "dataset:parse",
                "dataset",
                "parsed document JSON",
                tuple(f"data/interim/extracted_documents/{s}/**/*" for s in tokens),
            )
        )
    if "build" in stage_set:
        targets.append(
            Target(
                "dataset:build",
                "dataset",
                "raw_incidents CSV + meta.json (enrich also writes into these)",
                tuple(
                    pattern
                    for s in tokens
                    for pattern in (
                        f"dataset/csv/raw_incidents_{s}.csv",
                        f"dataset/csv/raw_incidents_{s}.meta.json",
                    )
                ),
            )
        )
    if "enrich" in stage_set:
        patterns = [
            pattern
            for s in tokens
            for pattern in (
                f"data/interim/enrichment_meta/{s}.json",
                f"{paths.reports}/tables/enrichment_report_{s}.json",
            )
        ]
        if not seasons:  # dated report covers all seasons; only remove on a full clean
            patterns.append(f"{paths.reports}/model_reports/enrichment_improvement_*.md")
        targets.append(
            Target("dataset:enrich", "dataset", "provenance sidecars, enrichment reports", tuple(patterns))
        )
    if "validate" in stage_set:
        targets.append(
            Target(
                "dataset:validate",
                "dataset",
                "processed + review_queue CSVs, data_quality reports",
                tuple(
                    pattern
                    for s in tokens
                    for pattern in (
                        f"dataset/csv/processed_{s}.csv",
                        f"dataset/csv/review_queue_{s}.csv",
                        f"{paths.reports}/tables/data_quality_{s}.json",
                    )
                ),
            )
        )
    if include_cache:
        if seasons:
            patterns = [
                pattern
                for s in tokens
                for pattern in (
                    f"{paths.ergast_cache}/{s}/**/*",
                    f"{paths.fastf1_cache}/{s}/**/*",
                    f"{paths.openf1_cache}/{s}/**/*",
                    f"{paths.openf1_cache}/openf1_sessions_{s}.json",
                )
            ]
        else:
            patterns = [
                f"{paths.ergast_cache}/**/*",
                f"{paths.fastf1_cache}/**/*",
                f"{paths.openf1_cache}/**/*",
            ]
        targets.append(
            Target(
                "dataset:cache",
                "dataset",
                "Ergast / FastF1 / OpenF1 API caches (FastF1 now needs an F1 TV login to refetch)",
                tuple(patterns),
                hard_to_recreate=True,
            )
        )
    return targets


def model_targets(phase: str, paths: OutputPaths) -> list[Target]:
    p, m, r = paths.processed, paths.models, paths.reports
    if phase == "v1":
        patterns = (
            *(f"{p}/{name}.parquet" for name in ("incidents", "features", "train", "validation", "test")),
            f"{m}/preprocessor.joblib",
            f"{m}/preprocessor.meta.json",
            f"{m}/xgboost/**/*",
            f"{m}/baseline/**/*",
            f"{r}/figures/confusion_matrix_val.png",
            f"{r}/figures/feature_importance_top20.png",
            f"{r}/figures/confusion_matrix_test.png",  # shared name: also written by V2
            f"{r}/model_reports/v1_training_report_*.md",
        )
        return [Target("v1", "v1", "prepare/encode parquet, baselines, XGBoost V1, reports", patterns)]
    if phase == "v2":
        patterns = (
            *(f"{p}/{name}.parquet" for name in ("features_v2", "train_v2", "validation_v2", "test_v2")),
            f"{m}/preprocessor_xgboost_v2.joblib",
            f"{m}/preprocessor_xgboost_v2.meta.json",
            f"{m}/xgboost_v2/**/*",
            f"{r}/ablation_results.json",
            f"{r}/selection_report_v2.json",
            f"{r}/figures/confusion_matrix_v2_val.png",
            f"{r}/figures/feature_importance_v2_top25.png",
            f"{r}/figures/v1_vs_v2_macro_f1.png",
            f"{r}/figures/confusion_matrix_test.png",
            f"{r}/model_reports/v2_feature_engineering_report_*.md",
        )
        return [Target("v2", "v2", "V2 features, XGBoost V2, ablation/selection, reports", patterns)]
    if phase == "nlp":
        patterns = (
            f"{p}/nlp_*.jsonl",
            f"{paths.nlp_models}/**/*",
            f"{r}/figures/nlp_confusion_matrix_val.png",
            f"{r}/model_reports/nlp_training_report_*.md",
            f"{r}/model_reports/nlp_comparison_*.md",
        )
        return [Target("nlp", "nlp", "text splits, DistilBERT model/checkpoints, fusion, reports", patterns)]
    if phase == "normative":
        patterns = (
            paths.normative_output,
            f"{paths.normative_models}/**/*",
            f"{paths.normative_reports}/**/*",
        )
        return [Target("normative", "normative", "normative predictions, rules version, deviation report", patterns)]
    raise ValueError(f"Unknown phase: {phase}")


# --------------------------------------------------------------------------- planning


@dataclass
class TargetPlan:
    target: Target
    files: list[Path] = field(default_factory=list)
    bytes: int = 0


@dataclass
class CleanPlan:
    root: Path
    phases: list[str]
    dataset_stages: list[str]
    seasons: list[int] | None
    targets: list[TargetPlan]
    skipped_unsafe: list[str] = field(default_factory=list)
    notes: list[str] = field(default_factory=list)

    @property
    def file_count(self) -> int:
        return sum(len(t.files) for t in self.targets)

    @property
    def total_bytes(self) -> int:
        return sum(t.bytes for t in self.targets)

    @property
    def hard_to_recreate(self) -> bool:
        return any(t.target.hard_to_recreate and t.files for t in self.targets)


def _is_under(path: Path, base: Path) -> bool:
    try:
        path.relative_to(base)
    except ValueError:
        return False
    return True


def is_safe_to_delete(path: Path, root: Path) -> bool:
    """True when ``path`` (resolved through any symlink) is an eligible generated file."""
    if path.name in PROTECTED_NAMES:
        return False
    root_resolved = root.resolve()
    try:
        resolved = path.resolve()
    except OSError:
        return False
    if not _is_under(resolved, root_resolved):
        return False
    if any(_is_under(resolved, root_resolved / p) for p in PROTECTED_ROOTS):
        return False
    return any(_is_under(resolved, root_resolved / a) for a in ALLOWED_ROOTS)


def _expand(pattern: str, root: Path) -> Iterable[Path]:
    if any(ch in pattern for ch in "*?["):
        return root.glob(pattern)
    candidate = root / pattern
    return [candidate] if candidate.exists() else []


def resolve_selection(
    *,
    only: list[str] | None,
    start_from: str | None,
    dataset_stages: list[str] | None,
    seasons: list[int] | None,
) -> list[str]:
    """Phases to clean. ``--season``/``--dataset-stage`` alone imply ``--only dataset``."""
    if only:
        return [phase for phase in PHASES if phase in set(only)]
    if start_from:
        return list(PHASES[PHASES.index(start_from):])
    if dataset_stages or seasons:
        return ["dataset"]
    return list(PHASES)


def build_plan(
    *,
    phases: list[str],
    dataset_stages: list[str] | None = None,
    seasons: list[int] | None = None,
    include_pdfs: bool = False,
    include_cache: bool = False,
    root: Path | None = None,
) -> CleanPlan:
    root = root or PROJECT_ROOT
    paths = OutputPaths.from_configs(root)

    stages = list(dataset_stages) if dataset_stages else list(DEFAULT_DATASET_STAGES)
    if include_pdfs and "download" not in stages:
        stages.insert(0, "download")
    stages = [s for s in DATASET_STAGES if s in stages]

    targets: list[Target] = []
    for phase in phases:
        if phase == "dataset":
            targets.extend(dataset_targets(stages, seasons, paths, include_cache=include_cache))
        else:
            targets.extend(model_targets(phase, paths))

    seen: set[Path] = set()
    skipped: list[str] = []
    plans: list[TargetPlan] = []
    for target in targets:
        plan = TargetPlan(target)
        for pattern in target.patterns:
            for path in _expand(pattern, root):
                if path.is_dir() and not path.is_symlink():
                    continue
                key = Path(os.path.normcase(str(path.absolute())))
                if key in seen:
                    continue
                if not is_safe_to_delete(path, root):
                    if path.name not in PROTECTED_NAMES:
                        skipped.append(str(path))
                    continue
                seen.add(key)
                plan.files.append(path)
                try:
                    plan.bytes += path.lstat().st_size
                except OSError:
                    pass
        plan.files.sort()
        plans.append(plan)

    notes: list[str] = []
    for phase in phases:
        stale = [d for d in DOWNSTREAM.get(phase, ()) if d not in phases]
        if phase == "dataset" and set(stages) <= {"download"}:
            continue  # removing PDFs alone doesn't change any built output
        if stale:
            notes.append(
                f"'{phase}' outputs feed {', '.join(stale)}; those are kept but will be stale "
                f"(main.py may report them as 'already ran'). Use --from {phase} to clean them too."
            )
    if "dataset" in phases and not include_pdfs and "download" not in stages:
        notes.append("FIA PDFs under data/raw/fia/ are kept (add --include-pdfs to delete them).")
    if "dataset" in phases and not include_cache:
        notes.append("API caches under data/raw/race_data/ are kept (add --include-cache to delete them).")

    return CleanPlan(
        root=root,
        phases=phases,
        dataset_stages=stages if "dataset" in phases else [],
        seasons=seasons,
        targets=plans,
        skipped_unsafe=skipped,
        notes=notes,
    )


# --------------------------------------------------------------------------- output / execution


def _fmt_bytes(num: int) -> str:
    size = float(num)
    for unit in ("B", "KB", "MB", "GB"):
        if size < 1024 or unit == "GB":
            return f"{size:.0f} {unit}" if unit == "B" else f"{size:.1f} {unit}"
        size /= 1024
    return f"{size:.1f} GB"  # pragma: no cover


def _display(path: Path, root: Path) -> str:
    try:
        return path.relative_to(root).as_posix()
    except ValueError:
        return str(path)


def format_plan(plan: CleanPlan, *, list_all: bool = False) -> str:
    """Human-readable summary of what a plan would delete."""
    lines = ["Clean plan", f"  phases:  {', '.join(plan.phases) or '(none)'}"]
    if plan.dataset_stages:
        lines.append(f"  dataset: {', '.join(plan.dataset_stages)}")
    lines.append(f"  seasons: {', '.join(map(str, plan.seasons)) if plan.seasons else 'all'}")
    lines.append("")
    for item in plan.targets:
        flag = "  [hard to recreate]" if item.target.hard_to_recreate and item.files else ""
        lines.append(
            f"[{item.target.name}] {len(item.files)} files, {_fmt_bytes(item.bytes)} "
            f"- {item.target.description}{flag}"
        )
        shown = item.files if list_all else item.files[:PREVIEW_LIMIT]
        lines.extend(f"    {_display(path, plan.root)}" for path in shown)
        hidden = len(item.files) - len(shown)
        if hidden > 0:
            lines.append(f"    ... and {hidden} more (use --list to show all)")
    lines.append("")
    lines.append(f"Total: {plan.file_count} files, {_fmt_bytes(plan.total_bytes)}")
    if plan.skipped_unsafe:
        lines.append(f"Refused {len(plan.skipped_unsafe)} path(s) outside generated-output folders:")
        lines.extend(f"    {p}" for p in plan.skipped_unsafe[:PREVIEW_LIMIT])
    for note in plan.notes:
        lines.append(f"Note: {note}")
    return "\n".join(lines)


def _prune_empty_dirs(deleted: Iterable[Path], root: Path) -> int:
    """Remove folders left empty by the deletion, stopping at structural folders."""
    root_resolved = root.resolve()
    candidates: set[Path] = set()
    for path in deleted:
        parent = path.parent
        while _is_under(parent.resolve(), root_resolved) and parent.resolve() != root_resolved:
            candidates.add(parent)
            parent = parent.parent
    removed = 0
    for directory in sorted(candidates, key=lambda p: len(p.parts), reverse=True):
        rel = _display(directory, root)
        if rel in STRUCTURAL_DIRS or not directory.is_dir() or directory.is_symlink():
            continue
        if not any(_is_under(directory.resolve(), root_resolved / a) for a in ALLOWED_ROOTS):
            continue
        try:
            directory.rmdir()  # only succeeds when empty
            removed += 1
        except OSError:
            pass
    return removed


@dataclass
class CleanResult:
    """Outcome of :func:`execute_plan`."""

    deleted: int
    freed_bytes: int
    removed_dirs: int
    errors: list[str]


def execute_plan(plan: CleanPlan) -> CleanResult:
    """Delete the planned files (re-checking each one), then prune emptied folders."""
    deleted: list[Path] = []
    freed = 0
    errors: list[str] = []
    for item in plan.targets:
        for path in item.files:
            if not is_safe_to_delete(path, plan.root):  # re-check right before deleting
                errors.append(f"{_display(path, plan.root)}: refused (no longer safe)")
                continue
            try:
                size = path.lstat().st_size
                path.unlink()
            except FileNotFoundError:
                continue
            except OSError as exc:
                errors.append(f"{_display(path, plan.root)}: {exc}")
                continue
            deleted.append(path)
            freed += size
    removed_dirs = _prune_empty_dirs(deleted, plan.root)
    return CleanResult(len(deleted), freed, removed_dirs, errors)


def confirm(plan: CleanPlan, *, assume_yes: bool, confirm_fn: Callable[[str], str] | None = None) -> bool:
    """Ask before deleting; hard-to-recreate data needs the full word 'yes'."""
    if assume_yes:
        return True
    strong = plan.hard_to_recreate
    message = (
        f"Delete {plan.file_count} files ({_fmt_bytes(plan.total_bytes)}), including data that is "
        "hard to recreate? Type 'yes' to confirm: "
        if strong
        else f"Delete {plan.file_count} files ({_fmt_bytes(plan.total_bytes)})? [y/N]: "
    )
    if confirm_fn is None:
        if not sys.stdin.isatty():
            print("Not an interactive terminal; pass --yes to delete without prompting.", file=sys.stderr)
            return False
        confirm_fn = input
    answer = confirm_fn(message).strip().lower()
    return answer == "yes" if strong else answer in {"y", "yes"}


# --------------------------------------------------------------------------- CLI


def build_parser() -> argparse.ArgumentParser:
    """Command-line options for clean.py."""
    parser = argparse.ArgumentParser(
        prog="clean.py",
        description=(
            "Delete files generated by main.py and the dataset pipeline. "
            "Previews by default; nothing is deleted without --run."
        ),
    )
    parser.add_argument("--dry-run", action="store_true", help="Show what would be deleted, then exit")
    parser.add_argument("--run", action="store_true", help="Delete (asks for confirmation unless --yes)")
    parser.add_argument("--yes", "-y", action="store_true", help="Skip the confirmation prompt")
    parser.add_argument(
        "--only",
        action="append",
        choices=PHASES,
        help="Clean only this phase (repeatable, e.g. --only v1 --only v2)",
    )
    parser.add_argument(
        "--from",
        dest="start_from",
        choices=PHASES,
        help="Clean this phase and every later phase (e.g. --from v1 = v1, v2, nlp, normative)",
    )
    parser.add_argument(
        "--dataset-stage",
        action="append",
        choices=DATASET_STAGES,
        dest="dataset_stages",
        help="Dataset stage(s) to clean (repeatable; default: parse, build, enrich, validate)",
    )
    parser.add_argument(
        "--season",
        type=int,
        action="append",
        dest="seasons",
        help="Dataset season(s) to clean (repeatable; default: every season on disk)",
    )
    parser.add_argument(
        "--include-pdfs",
        action="store_true",
        help="Also delete downloaded FIA PDFs, manifest.json and download_failures.json",
    )
    parser.add_argument(
        "--include-cache",
        action="store_true",
        help="Also delete Ergast / FastF1 / OpenF1 API caches",
    )
    parser.add_argument(
        "--purge",
        action="store_true",
        help="Everything: all phases + --include-pdfs + --include-cache",
    )
    parser.add_argument("--list", action="store_true", help="List every file instead of a preview")
    return parser


def main(argv: list[str] | None = None, *, confirm_fn: Callable[[str], str] | None = None) -> int:
    """CLI entry point. Returns 0 on success, 1 if aborted or a file failed, 2 for help only."""
    parser = build_parser()
    args = parser.parse_args(argv)

    if not args.run and not args.dry_run:
        parser.print_help()
        print(
            "\nNothing deleted. Pass --dry-run to preview or --run to delete.",
            file=sys.stderr,
        )
        return 2
    if args.only and args.start_from:
        parser.error("Use either --only or --from, not both.")
    if args.purge and (args.only or args.start_from or args.dataset_stages or args.seasons):
        parser.error("--purge cleans everything; don't combine it with --only/--from/--dataset-stage/--season.")

    include_pdfs = args.include_pdfs or args.purge
    include_cache = args.include_cache or args.purge
    phases = resolve_selection(
        only=args.only,
        start_from=args.start_from,
        dataset_stages=args.dataset_stages,
        seasons=args.seasons,
    )
    if (args.seasons or args.dataset_stages or include_pdfs or include_cache) and "dataset" not in phases:
        parser.error(
            "--season, --dataset-stage, --include-pdfs and --include-cache apply to the dataset phase; "
            "add --only dataset (or --from dataset)."
        )
    if args.seasons and phases != ["dataset"]:
        parser.error(
            "--season only applies to the dataset phase (v1/v2/nlp/normative are not per season); "
            "use --only dataset."
        )

    plan = build_plan(
        phases=phases,
        dataset_stages=args.dataset_stages,
        seasons=args.seasons,
        include_pdfs=include_pdfs,
        include_cache=include_cache,
    )
    print(format_plan(plan, list_all=args.list))

    if args.dry_run or not args.run:
        print("\nDry run: nothing deleted.")
        return 0
    if plan.file_count == 0:
        print("\nNothing to delete.")
        return 0
    if not confirm(plan, assume_yes=args.yes, confirm_fn=confirm_fn):
        print("Aborted: nothing deleted.")
        return 1

    result = execute_plan(plan)
    print(
        f"\nDeleted {result.deleted} files ({_fmt_bytes(result.freed_bytes)}), "
        f"removed {result.removed_dirs} empty folders."
    )
    if result.errors:
        print(f"{len(result.errors)} file(s) could not be deleted:", file=sys.stderr)
        for error in result.errors[:PREVIEW_LIMIT]:
            print(f"    {error}", file=sys.stderr)
        return 1
    print("Tracked files show as deleted in git; 'git restore <path>' brings them back.")
    return 0
